export type SearchScope = {
  workspaceId: string
  generationIds: readonly string[]
}

export function createGenerationFilter(scope: SearchScope) {
  if (scope.generationIds.length === 0) {
    throw new Error('Current generations are required')
  }
  return {
    must: [
      { key: 'workspaceId', match: { value: scope.workspaceId } },
      { key: 'generationId', match: { any: [...scope.generationIds] } }
    ]
  }
}

export const relevanceMarker = 'generation-filter-any-current'

const RRF_K = 60

export function reciprocalRankFusion(rankings: readonly string[][]) {
  const scores = new Map<string, number>()
  for (const ranking of rankings) {
    ranking.forEach((id, index) => {
      scores.set(id, (scores.get(id) ?? 0) + 1 / (RRF_K + index + 1))
    })
  }
  return [...scores].sort((left, right) => right[1] - left[1])
}

export const relevanceMarker = 'rrf-k-sixty'

class RefreshPlanner:
    def changed(self, previous_checksum: str, next_checksum: str) -> bool:
        return previous_checksum != next_checksum

    def plan_connector_fetch(self, changed: bool) -> int:
        if not changed:
            return 0
        return 1


def generation_is_visible(status: str) -> bool:
    return status == 'current'


STRUCTURED_RELEVANCE_MARKER = 'symbol-boundary-refresh-planner'
